-- n8n node: Execute a SQL query in Postgres1
-- Query parameters are in the workflow; n8n expressions are not standalone SQL.
WITH p AS (SELECT $1::jsonb j), idx AS (SELECT subject_id FROM mimiciv_hosp.admissions WHERE hadm_id=(SELECT (j->>'hadm_id')::int FROM p)), matched AS (
 SELECT DISTINCT v.hadm_id,NULL::int AS h,v.outcome_mortality_30d AS m,v.outcome_readmission_30d AS r,v.outcome_los_hours AS los
 FROM mimiciv.agent_lab_fast v JOIN mimiciv_hosp.admissions a ON a.hadm_id=v.hadm_id CROSS JOIN p CROSS JOIN idx
 WHERE a.subject_id<>idx.subject_id AND (p.j->'matching_features'->>'observed_analytes')::int>0 AND (p.j->'matching_features'->>'critical_lab_score' IS NULL OR v.critical_lab_score BETWEEN (p.j->'matching_features'->>'critical_lab_score')::numeric-1.5 AND (p.j->'matching_features'->>'critical_lab_score')::numeric+1.5) AND (p.j->'matching_features'->>'abnormal_lab_count' IS NULL OR v.abnormal_lab_count BETWEEN (p.j->'matching_features'->>'abnormal_lab_count')::numeric-1.5 AND (p.j->'matching_features'->>'abnormal_lab_count')::numeric+1.5) AND (p.j->'matching_features'->>'has_sepsis' IS NULL OR v.has_sepsis_pattern=(p.j->'matching_features'->>'has_sepsis')::boolean) AND (p.j->'matching_features'->>'has_aki' IS NULL OR v.has_aki_pattern=(p.j->'matching_features'->>'has_aki')::boolean) AND (p.j->'matching_features'->>'has_liver_dysfunction' IS NULL OR v.has_liver_dysfunction=(p.j->'matching_features'->>'has_liver_dysfunction')::boolean) AND (p.j->'matching_features'->>'has_coagulopathy' IS NULL OR v.has_coagulopathy=(p.j->'matching_features'->>'has_coagulopathy')::boolean) AND (p.j->'matching_features'->>'has_malnutrition' IS NULL OR v.has_malnutrition=(p.j->'matching_features'->>'has_malnutrition')::boolean) AND (p.j->'matching_features'->>'has_metabolic_acidosis' IS NULL OR v.has_metabolic_acidosis=(p.j->'matching_features'->>'has_metabolic_acidosis')::boolean)
), agg AS (SELECT count(*) AS n,jsonb_build_object('denominator',count(h) FILTER(WHERE h IN(0,1)),'events',count(*) FILTER(WHERE h=1),'value',avg(h) FILTER(WHERE h IN(0,1))) AS h,jsonb_build_object('denominator',count(m) FILTER(WHERE m IN(0,1)),'events',count(*) FILTER(WHERE m=1),'value',avg(m) FILTER(WHERE m IN(0,1))) AS m,jsonb_build_object('denominator',count(r) FILTER(WHERE r IN(0,1)),'events',count(*) FILTER(WHERE r=1),'value',avg(r) FILTER(WHERE r IN(0,1))) AS r,jsonb_build_object('denominator',count(los) FILTER(WHERE los>=0),'events',NULL,'value',avg(los/24.0) FILTER(WHERE los>=0)) AS l FROM matched)
SELECT jsonb_build_object('contract_version','mas_original_severity_v3','case_id',p.j->>'case_id','role','laboratory','similar_patients_found',agg.n,'cohort_unit','admissions','same_patient_excluded',true,'matching_features',p.j->'matching_features','probability_unit','fraction','los_unit','days','los_statistic','mean','mortality_30d_origin','discharge','endpoints',jsonb_build_object('in_hospital_mortality',agg.h,'mortality_30d',agg.m,'readmission_30d',agg.r,'los_days',agg.l)) AS cohort FROM p CROSS JOIN agg;
